import{_ as i,o as a,c as e,a2 as p}from"./chunks/framework.F7eQ-ohH.js";const t="/bzygq/assets/quesion_imgs_image_1763782015721_651.6_hmxQ3I.png",r="/bzygq/assets/quesion_imgs_image_1763782023212_823.mOSDpkAo.png",m=JSON.parse('{"title":"5.半结构化面试概述","description":"","frontmatter":{},"headers":[],"relativePath":"docs/面试指南/5.半结构化面试概述.md","filePath":"docs/面试指南/5.半结构化面试概述.md","lastUpdated":1788881428000}'),o={name:"docs/面试指南/5.半结构化面试概述.md"};function s(n,l,h,d,_,u){return a(),e("div",null,[...l[0]||(l[0]=[p('<h1 id="_5-半结构化面试概述" tabindex="-1">5.半结构化面试概述 <a class="header-anchor" href="#_5-半结构化面试概述" aria-label="Permalink to &quot;5.半结构化面试概述&quot;">​</a></h1><p><strong>央国企半结构化面试概述</strong></p><h1 id="半结构化面试到底是个啥" tabindex="-1">半结构化面试到底是个啥？ <a class="header-anchor" href="#半结构化面试到底是个啥" aria-label="Permalink to &quot;半结构化面试到底是个啥？&quot;">​</a></h1><h2 id="半结构化-结构化到底有啥区别" tabindex="-1">半结构化&amp;结构化到底有啥区别？ <a class="header-anchor" href="#半结构化-结构化到底有啥区别" aria-label="Permalink to &quot;半结构化&amp;结构化到底有啥区别？&quot;">​</a></h2><p>半结构化面试和结构化面试一样，又一个高大上的名字，诈一听会让人觉得有些高不可攀觉得这玩意儿准备起来肯定非常难。</p><p>但是实际上就跟土豆叫土豆就很土，叫马铃薯就听起来很高大上一样，半结构化面试其实也就是一个披着狼皮的羊，实际上就是大家平时面试私企、国企遇到的最常见的面试方式——问答式面试。</p><p>前面我们讲了结构化面试，知道结构化面试的流程大概是面试官根据题本单方面的向你提出问题，然后你做出回答，面试官再根据你的回答情况按照标准评分，因此叫做结构化面试。结构化面试的整个过程中你和面试官是没有多余的交流的，你只是单方面回答，面试官也不会根据你的回答去追问更深入的问题。</p><p>而半结构化面试的面试官也有可能从固定的题目列表当中抽出问题（实际上大多数面试官都是临时从网上找的问题），也有可能根据你的简历、项目情况从你的自身经历出发去提问（这就是提前预埋陷阱的重要性）。你回答完之后，面试官还可能根据你的回答情况进行进一步追问，挖掘你的解决问题的能力和项目亮点。</p><p>总的来说就是，结构化面试你和面试官没有交流，按照严格的标准给你面试打分，突出一个公平性。半结构化面试就是你和面试官是有互动和交流的，能够发掘你的综合能力和经历信息。</p><h2 id="举个栗子" tabindex="-1">举个栗子 <a class="header-anchor" href="#举个栗子" aria-label="Permalink to &quot;举个栗子&quot;">​</a></h2><p>央国企的半结构化面试通常问题比较简单，是和你的学习生活，实习经历，研究生经历联系紧密的，可能会让应届生觉得面试容易，没有技术含量（但是这类央企大家不是应届生连面试机会都没有，一定要珍惜）。以下是帮大家总结的常见的半结构化面试的栗子：</p><p>半结构化面试是一种结合了结构化和非结构化特点的面试方式，它通常包含一些固定的问题和一些根据应聘者回答而提出的个性化问题。以下是一些常见的半结构化面试问题例子，并进行了分类总结：</p><ul><li>请简单介绍一下你自己。</li><li>你在大学/研究生期间最自豪的成就是什么？</li><li>谈谈你的一次失败经历，以及你从中学到的东西。</li><li>你认为自己的哪些特质适合应聘的职位？</li><li>你在平时的研究学习中有没有遇到压力比较大的情况？你是如何处理压力和挑战？</li><li>你为什么选择来成都？未来有定居成都的计划嘛？</li><li>你认为自己更适合团队中的什么角色？</li><li>描述一次你在团队中发挥作用的经历。</li><li>你为什么选择我们公司？</li><li>你的职业规划是什么？</li><li>你对大数据/人工智能在金融业的应用有何看法？</li><li>如果工作量超出了你的承受能力，你会怎么办？</li><li>你如何处理工作中的紧急情况？</li><li>你更愿意与哪种类型的同事合作？</li><li>描述一次你解决工作中人际关系问题的经历。</li><li>谈谈你在xxx公司的实习经历，你学到了什么？</li><li>如果你是团队负责人，如何处理团队成员的不当行为？</li></ul><p>上面这些都是一些常见的央企国企半结构化面试会遇到的问题，大家可以发现很多都跟技术无关，更侧重的是考察个人的综合能力。另外，还有一些半结构化面试的问题是会根据你的项目和研究经历来提问的，这个这里就没办法展开说了。</p><h1 id="半结构化面试到底考察什么" tabindex="-1">半结构化面试到底考察什么？ <a class="header-anchor" href="#半结构化面试到底考察什么" aria-label="Permalink to &quot;半结构化面试到底考察什么？&quot;">​</a></h1><p>通过上面的问题可以发现，半结构化面试问的范围比较广，但是同时呢也不会特别难更多的是一些和你工作、学历经历相关的问题。通过这些问题，评估应聘者的专业技能和行业知识，还能够考察应聘者的性格特点、工作态度、团队合作精神和问题解决能力。</p><p>但是半结构化面试就有一个比较玄学的问题，由于没有具体的评分标准，所以很大程度上你的面试评分跟面试官的个人兴趣、喜欢和专业知识积累高度关联。</p><p>从上面的问题可以看出，半结构化面试由于问题范围比较广，类型也比较多而且和个人的经历高度相关，因此很难像准备技术面试一样通过八股文背诵的方式去准备这一类的面试。</p><p>那么我们应该如何准备才能使得回答的问题更加贴合面试官的想法呢？才能够帮助你在半结构化面试当中获得更高的评价呢？</p><p>一个行之有效的方法其实就是对于这些半结构化面试分门别类的去总结，了解面试官在每一类问题之后希望得到一个什么样的答案，来集中面试官的心理想法，这才是半结构化面试的制胜秘诀。</p><p>本节后面的内容就会系统的帮大家总结和梳理，在此之前我们先了解一下常见的半结构化面试的形式。</p><h1 id="半结构化面试流程" tabindex="-1">半结构化面试流程 <a class="header-anchor" href="#半结构化面试流程" aria-label="Permalink to &quot;半结构化面试流程&quot;">​</a></h1><p>半结构化的面试形式一般分成2种，多对多和多对1，线上和线下面试都有可能，少数大型的央企会要求你参加线下面试，但是多数的还是线上面试就行了。这里我们主要以线下的面试为主，线上的面试多对多还是1对多都没啥区别。</p><h2 id="多对多形式" tabindex="-1">多对多形式 <a class="header-anchor" href="#多对多形式" aria-label="Permalink to &quot;多对多形式&quot;">​</a></h2><p>多对多形式在银行、军工、工程等各类央企都有，但是现在多对多面试的方式一般较少，这里还是给大家给出来：</p><p><img src="'+t+'" alt=""></p><p>央国企的半结构化面试大致包含下列流程，举个栗子：</p><ul><li><p><strong>第一步先是所有人依次进行自我介绍，介绍的时候面试官会浏览你的简历</strong></p></li><li><p>自我介绍完毕之后呢，面试官会对自己感兴趣的人进行提问，大部分都是根据你简历进行提问的，也会有人资的HR问一些HR相关问题。由于人比较多，所以回答时间一般限制在2分钟以内。</p></li><li><p>因为前面是根据面试官的偏好对感兴趣的学生提问，为了避免有的同学过于尴尬，因此会有一名面试官来问没被提问的孩子，让每个人都有展现自我的机会。</p></li></ul><p>总的来说，多对多的面试形式肯定会导致每个人的发言时间较少，所以要抓住机会来吸引面试官的眼球。但是也不是被问到了就一直东说西说，而是应该把握住机会，在极短的时间之内把自己的核心优势说出来即可。</p><h2 id="多对一形式" tabindex="-1">多对一形式 <a class="header-anchor" href="#多对一形式" aria-label="Permalink to &quot;多对一形式&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>多对一的面试形式可能是线上的，也可能是线下的，面试的流程一般如下：</p><ul><li><p>首先还是自我介绍，有一位主考官会让你做自我介绍。</p></li><li><p>自我介绍后，主考官<strong>直接抛出了4-5个问题</strong>，一次性说出，如果没有听清楚可以让考官重复。</p></li><li><p>这4-5个问题可以在8分钟内回答完毕，可以思考一段时间再回答，也可以回答一个后，思考下一道问题，然后再回答一个，时间安排比较自由。</p></li><li><p>全部问题回答完毕后，会有考官根据你之前的回答追问一些细节，这就是半结构的一个特点，有追问互动环节。</p></li></ul><h2 id="普通面试-单面" tabindex="-1">普通面试/单面 <a class="header-anchor" href="#普通面试-单面" aria-label="Permalink to &quot;普通面试/单面&quot;">​</a></h2><p>普通面试的形式就不用多说了，大家去互联网和各种私企面试形式差不多，主要都是针对你简历、项目等情况来进行面试。</p><p>面试题类型</p><p>通常半结构的面试题型只有那么几类，多数半结构化的面试题来来回回都是那些，这些简单的给大家总结一下：</p><p><strong>个人经历类（简历相关，必问）</strong></p><ul><li>讲一讲你大学/研究生生涯中最有成就的一件事情</li><li>你可以简单的讲述一下你在xxx这段实习经历吗？你从中最大的收获是什么？</li><li>讲一讲你印象中最失败的一次经历</li></ul><p><strong>求职意愿类（稳定性问题，考察你会不会来，以及来了会不会离职）</strong></p><ul><li>你为什么参加我们公司面试？</li><li>有没有参加过其它公司的面试？</li><li>手里还有其它offer没有？</li><li>为什么选择成都，以后考虑在那里定居？</li></ul><p><strong>个性特征类</strong></p><ul><li>你最大的缺点是什么？</li><li>你最大的优点是什么？</li><li>同事和上级都是如何评价你的？</li><li>你觉得你在团队中更适合什么样的角色？是领导者、还是实干家？</li></ul><p><strong>沟通类</strong></p><ul><li>如果你的领导一直给你增派任务，你忙不过来而导致很多工作延误，你应该怎么办？</li><li>你在工作中最不愿意和哪一类人一起合作共事？为什么？</li></ul><p><strong>综合分析类</strong></p><ul><li>随着人工智能AI的发展，银行应当如何借此机会开展业务？</li><li>公众场合的一些不文明行为，如随地吐痰、抽烟等，未来将会计入信用档案，谈谈你的看法？</li><li>你对无人银行的出现有什么看法？</li></ul><h1 id="end" tabindex="-1">END <a class="header-anchor" href="#end" aria-label="Permalink to &quot;END&quot;">​</a></h1><p>总的来说，央国企的半结构化面试还是非常简单的，和私企喜欢问技术不同，央国企的半结构化面试更加喜欢问的是和个人的综合能力、表达能力相关的问题，反而对技术能力没有那么关注。</p>',49)])])}const g=i(o,[["render",s]]);export{m as __pageData,g as default};
